import 'package:flutter/material.dart';
import 'package:just_audio/just_audio.dart';

class BasicAudioPlayerScreen extends StatefulWidget {
  const BasicAudioPlayerScreen({super.key});

  @override
  State<BasicAudioPlayerScreen> createState() => _BasicAudioPlayerScreenState();
}

class _BasicAudioPlayerScreenState extends State<BasicAudioPlayerScreen> {
  late AudioPlayer _player;

  @override
  void initState() {
    super.initState();
    _player = AudioPlayer();
    _loadAudio();
  }

  Future<void> _loadAudio() async {
    try {
      // 네트워크 URL에서 로드
      await _player.setUrl(
        'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3',
      );

      // 또는 로컬 에셋에서 로드
      // await _player.setAsset('assets/audio/music.mp3');

      // 또는 로컬 파일에서 로드
      // await _player.setFilePath('/path/to/file.mp3');
    } catch (e) {
      debugPrint('오디오 로드 오류: $e');
    }
  }

  @override
  void dispose() {
    _player.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('오디오 플레이어')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 재생 상태 스트림
            StreamBuilder<PlayerState>(
              stream: _player.playerStateStream,
              builder: (context, snapshot) {
                final state = snapshot.data;
                final playing = state?.playing ?? false;
                final processingState = state?.processingState;

                // 로딩 중
                if (processingState == ProcessingState.loading ||
                    processingState == ProcessingState.buffering) {
                  return const CircularProgressIndicator();
                }

                // 재생/일시정지 버튼
                return IconButton(
                  iconSize: 64,
                  icon: Icon(playing ? Icons.pause : Icons.play_arrow),
                  onPressed: () {
                    if (playing) {
                      _player.pause();
                    } else {
                      _player.play();
                    }
                  },
                );
              },
            ),
            const SizedBox(height: 20),
            // 진행 바
            StreamBuilder<Duration?>(
              stream: _player.positionStream,
              builder: (context, snapshot) {
                final position = snapshot.data ?? Duration.zero;
                final duration = _player.duration ?? Duration.zero;

                return Column(
                  children: [
                    Slider(
                      value: position.inMilliseconds.toDouble(),
                      max: duration.inMilliseconds.toDouble(),
                      onChanged: (value) {
                        _player.seek(Duration(milliseconds: value.toInt()));
                      },
                    ),
                    Text(
                      '${_formatDuration(position)} / ${_formatDuration(duration)}',
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }

  String _formatDuration(Duration duration) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    final minutes = twoDigits(duration.inMinutes.remainder(60));
    final seconds = twoDigits(duration.inSeconds.remainder(60));
    return '$minutes:$seconds';
  }
}

import 'package:flutter/material.dart';
import 'package:just_audio/just_audio.dart';

class AudioControlsExample extends StatefulWidget {
  const AudioControlsExample({super.key});

  @override
  State<AudioControlsExample> createState() => _AudioControlsExampleState();
}

class _AudioControlsExampleState extends State<AudioControlsExample> {
  late AudioPlayer _player;
  double _volume = 1.0;
  double _speed = 1.0;
  LoopMode _loopMode = LoopMode.off;

  @override
  void initState() {
    super.initState();
    _player = AudioPlayer();
    _player.setUrl('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3');
  }

  @override
  void dispose() {
    _player.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('재생 컨트롤')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            // 재생 버튼들
            StreamBuilder<PlayerState>(
              stream: _player.playerStateStream,
              builder: (context, snapshot) {
                final playing = snapshot.data?.playing ?? false;
                return Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    // 10초 뒤로
                    IconButton(
                      icon: const Icon(Icons.replay_10),
                      onPressed: () {
                        final position = _player.position;
                        _player.seek(position - const Duration(seconds: 10));
                      },
                    ),
                    // 재생/일시정지
                    IconButton(
                      iconSize: 48,
                      icon: Icon(playing ? Icons.pause : Icons.play_arrow),
                      onPressed: () {
                        playing ? _player.pause() : _player.play();
                      },
                    ),
                    // 정지 (처음으로)
                    IconButton(
                      icon: const Icon(Icons.stop),
                      onPressed: () {
                        _player.stop();
                      },
                    ),
                    // 10초 앞으로
                    IconButton(
                      icon: const Icon(Icons.forward_10),
                      onPressed: () {
                        final position = _player.position;
                        _player.seek(position + const Duration(seconds: 10));
                      },
                    ),
                  ],
                );
              },
            ),
            const SizedBox(height: 24),

            // 진행 바
            StreamBuilder<Duration?>(
              stream: _player.positionStream,
              builder: (context, snapshot) {
                final position = snapshot.data ?? Duration.zero;
                final duration = _player.duration ?? Duration.zero;
                return Slider(
                  value: position.inSeconds.toDouble().clamp(
                    0,
                    duration.inSeconds.toDouble(),
                  ),
                  max: duration.inSeconds.toDouble(),
                  onChanged: (value) {
                    _player.seek(Duration(seconds: value.toInt()));
                  },
                );
              },
            ),
            const SizedBox(height: 24),

            // 볼륨
            Row(
              children: [
                const Icon(Icons.volume_down),
                Expanded(
                  child: Slider(
                    value: _volume,
                    onChanged: (value) {
                      setState(() => _volume = value);
                      _player.setVolume(value);
                    },
                  ),
                ),
                const Icon(Icons.volume_up),
              ],
            ),

            // 재생 속도
            Row(
              children: [
                const Text('속도: '),
                Expanded(
                  child: Slider(
                    value: _speed,
                    min: 0.5,
                    max: 2.0,
                    divisions: 6,
                    label: '${_speed}x',
                    onChanged: (value) {
                      setState(() => _speed = value);
                      _player.setSpeed(value);
                    },
                  ),
                ),
                Text('${_speed}x'),
              ],
            ),

            // 루프 모드
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Text('반복: '),
                SegmentedButton<LoopMode>(
                  segments: const [
                    ButtonSegment(value: LoopMode.off, label: Text('끔')),
                    ButtonSegment(value: LoopMode.one, label: Text('한 곡')),
                    ButtonSegment(value: LoopMode.all, label: Text('전체')),
                  ],
                  selected: {_loopMode},
                  onSelectionChanged: (modes) {
                    setState(() => _loopMode = modes.first);
                    _player.setLoopMode(_loopMode);
                  },
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:just_audio/just_audio.dart';

class PlaylistExample extends StatefulWidget {
  const PlaylistExample({super.key});

  @override
  State<PlaylistExample> createState() => _PlaylistExampleState();
}

class _PlaylistExampleState extends State<PlaylistExample> {
  late AudioPlayer _player;
  late ConcatenatingAudioSource _playlist;

  final List<Map<String, String>> _tracks = [
    {'title': 'Song 1', 'url': 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3'},
    {'title': 'Song 2', 'url': 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3'},
    {'title': 'Song 3', 'url': 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-3.mp3'},
  ];

  @override
  void initState() {
    super.initState();
    _player = AudioPlayer();
    _setupPlaylist();
  }

  Future<void> _setupPlaylist() async {
    _playlist = ConcatenatingAudioSource(
      children: _tracks.map((track) {
        return AudioSource.uri(
          Uri.parse(track['url']!),
          tag: track['title'], // 메타데이터
        );
      }).toList(),
    );

    await _player.setAudioSource(_playlist);
  }

  @override
  void dispose() {
    _player.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('플레이리스트')),
      body: Column(
        children: [
          // 현재 재생 중인 트랙
          StreamBuilder<int?>(
            stream: _player.currentIndexStream,
            builder: (context, snapshot) {
              final index = snapshot.data ?? 0;
              return Container(
                padding: const EdgeInsets.all(16),
                color: Colors.blue[100],
                child: Row(
                  children: [
                    const Icon(Icons.music_note, size: 48),
                    const SizedBox(width: 16),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text('Now Playing', style: TextStyle(fontSize: 12)),
                          Text(
                            _tracks[index]['title']!,
                            style: const TextStyle(
                              fontSize: 20,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              );
            },
          ),

          // 컨트롤 버튼
          Padding(
            padding: const EdgeInsets.all(16),
            child: StreamBuilder<PlayerState>(
              stream: _player.playerStateStream,
              builder: (context, snapshot) {
                final playing = snapshot.data?.playing ?? false;
                return Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    // 셔플
                    StreamBuilder<bool>(
                      stream: _player.shuffleModeEnabledStream,
                      builder: (context, snapshot) {
                        final enabled = snapshot.data ?? false;
                        return IconButton(
                          icon: Icon(
                            Icons.shuffle,
                            color: enabled ? Colors.blue : null,
                          ),
                          onPressed: () {
                            _player.setShuffleModeEnabled(!enabled);
                          },
                        );
                      },
                    ),
                    // 이전 곡
                    IconButton(
                      icon: const Icon(Icons.skip_previous),
                      iconSize: 36,
                      onPressed: () => _player.seekToPrevious(),
                    ),
                    // 재생/일시정지
                    IconButton(
                      icon: Icon(playing ? Icons.pause : Icons.play_arrow),
                      iconSize: 48,
                      onPressed: () {
                        playing ? _player.pause() : _player.play();
                      },
                    ),
                    // 다음 곡
                    IconButton(
                      icon: const Icon(Icons.skip_next),
                      iconSize: 36,
                      onPressed: () => _player.seekToNext(),
                    ),
                    // 반복
                    StreamBuilder<LoopMode>(
                      stream: _player.loopModeStream,
                      builder: (context, snapshot) {
                        final mode = snapshot.data ?? LoopMode.off;
                        final icons = {
                          LoopMode.off: Icons.repeat,
                          LoopMode.one: Icons.repeat_one,
                          LoopMode.all: Icons.repeat,
                        };
                        return IconButton(
                          icon: Icon(
                            icons[mode],
                            color: mode != LoopMode.off ? Colors.blue : null,
                          ),
                          onPressed: () {
                            final modes = LoopMode.values;
                            final nextIndex = (modes.indexOf(mode) + 1) % modes.length;
                            _player.setLoopMode(modes[nextIndex]);
                          },
                        );
                      },
                    ),
                  ],
                );
              },
            ),
          ),

          // 트랙 목록
          Expanded(
            child: ListView.builder(
              itemCount: _tracks.length,
              itemBuilder: (context, index) {
                return StreamBuilder<int?>(
                  stream: _player.currentIndexStream,
                  builder: (context, snapshot) {
                    final currentIndex = snapshot.data;
                    final isPlaying = currentIndex == index;

                    return ListTile(
                      leading: CircleAvatar(
                        backgroundColor: isPlaying ? Colors.blue : Colors.grey,
                        child: Text('${index + 1}'),
                      ),
                      title: Text(
                        _tracks[index]['title']!,
                        style: TextStyle(
                          fontWeight: isPlaying ? FontWeight.bold : null,
                          color: isPlaying ? Colors.blue : null,
                        ),
                      ),
                      trailing: isPlaying
                          ? const Icon(Icons.equalizer, color: Colors.blue)
                          : null,
                      onTap: () => _player.seek(Duration.zero, index: index),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

