class BackgroundAudioPlayer extends StatefulWidget {
  const BackgroundAudioPlayer({super.key});

  @override
  State<BackgroundAudioPlayer> createState() => _BackgroundAudioPlayerState();
}

class _BackgroundAudioPlayerState extends State<BackgroundAudioPlayer> {
  late AudioPlayer _player;

  @override
  void initState() {
    super.initState();
    _player = AudioPlayer();
    _setupAudio();
  }

  Future<void> _setupAudio() async {
    // 메타데이터 포함하여 로드
    await _player.setAudioSource(
      AudioSource.uri(
        Uri.parse('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3'),
        tag: MediaItem(
          id: '1',
          title: 'Song Title',
          artist: 'Artist Name',
          album: 'Album Name',
          artUri: Uri.parse('https://example.com/album_art.jpg'),
        ),
      ),
    );
  }

  @override
  void dispose() {
    _player.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('백그라운드 재생')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            const Text('앱을 백그라운드로 전환해도\n음악이 계속 재생됩니다'),
            const SizedBox(height: 20),
            StreamBuilder<PlayerState>(
              stream: _player.playerStateStream,
              builder: (context, snapshot) {
                final playing = snapshot.data?.playing ?? false;
                return IconButton(
                  iconSize: 64,
                  icon: Icon(playing ? Icons.pause : Icons.play_arrow),
                  onPressed: () {
                    playing ? _player.pause() : _player.play();
                  },
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

